package app.bean.focus;
import android.app.*;import android.os.*;import android.app.usage.*;import android.app.AppOpsManager;import android.content.*;import android.graphics.Color;import android.provider.Settings;import android.webkit.*;import android.widget.*;import org.json.*;import java.util.*;import java.time.*;import java.io.*;
public class StatsActivity extends Activity {
 private WebView web;private TextView status;private boolean busy=false;private long lastRefresh;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.WHITE);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});setContentView(root);
  LinearLayout tools=new LinearLayout(this);for(String label:new String[]{"←","사용정보 권한","새로고침","채널"}){Button bt=new Button(this);bt.setText(label);bt.setTextSize(11);tools.addView(bt,new LinearLayout.LayoutParams(0,-2,1));bt.setOnClickListener(v->{if(label.equals("←"))finish();else if(label.equals("사용정보 권한"))startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS));else if(label.equals("채널"))channels();else refresh();});}root.addView(tools);status=new TextView(this);status.setTextSize(12);status.setPadding(14,8,14,8);root.addView(status);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));
 }
 protected void onResume(){super.onResume();if(SystemClock.elapsedRealtime()-lastRefresh>1500)refresh();}
 private boolean access(){AppOpsManager ops=(AppOpsManager)getSystemService(APP_OPS_SERVICE);return ops.checkOpNoThrow(AppOpsManager.OPSTR_GET_USAGE_STATS,android.os.Process.myUid(),getPackageName())==AppOpsManager.MODE_ALLOWED;}
 private void refresh(){if(busy)return;busy=true;status.setText("기기에 저장된 기록을 계산하는 중…");new Thread(()->{boolean allowed=access();String warning="";try{if(allowed)importGames();}catch(Exception e){warning=" · 게임 기록 가져오기 실패";}JSONObject data=AnalyticsDb.get(this).snapshot();try{data.put("usageAccess",allowed);data.put("zone",ZoneId.systemDefault().toString());}catch(Exception ignored){}String html="";try{InputStream in=getAssets().open("stats.html");ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);in.close();html=b.toString("UTF-8").replace("__BEAN_DATA__",data.toString().replace("<","\\u003c")).replace("__BEAN_CORE__",readAsset("stats_core.js"));}catch(Exception ignored){}final String page=html,msg=(allowed?"게임: Android 앱 사용 기록":"게임 통계: 사용정보 접근 권한 필요")+warning+" · 웹: v0.4 이후 관측 기록";runOnUiThread(()->{if(isFinishing()||isDestroyed())return;busy=false;lastRefresh=SystemClock.elapsedRealtime();status.setText(msg);web.loadDataWithBaseURL("https://bean.invalid/",page,"text/html","UTF-8",null);});},"bean-stats").start();}
 private void importGames(){UsageStatsManager m=(UsageStatsManager)getSystemService(USAGE_STATS_SERVICE);long start=LocalDate.now().minusDays(62).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();List<UsageStats> stats=m.queryUsageStats(UsageStatsManager.INTERVAL_DAILY,start,System.currentTimeMillis());if(stats==null||stats.isEmpty())return;Map<String,Map<String,Long>> byDay=new HashMap<>();Set<String> covered=new HashSet<>(),selected=Prefs.games(this);for(UsageStats stat:stats){String day=AnalyticsDb.day(stat.getFirstTimeStamp());covered.add(day);if(!selected.contains(stat.getPackageName()))continue;Map<String,Long> row=byDay.get(day);if(row==null){row=new HashMap<>();byDay.put(day,row);}Long old=row.get(stat.getPackageName());row.put(stat.getPackageName(),(old==null?0:old)+stat.getTotalTimeInForeground());}AnalyticsDb.get(this).replaceGameDays(byDay,covered);Prefs.get(this).edit().putLong("stats_game_import",System.currentTimeMillis()).apply();}
 private String readAsset(String name) throws IOException {InputStream in=getAssets().open(name);ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);in.close();return b.toString("UTF-8");}
 private void channels(){JSONArray list=AnalyticsDb.get(this).channels();String[] names=new String[list.length()];for(int i=0;i<names.length;i++){JSONObject row=list.optJSONObject(i);names[i]=row.optString("name")+" · "+(row.optString("kind").equals("lecture")?"강의":row.optString("kind").equals("leisure")?"여가":"미분류");}if(names.length==0){Toast.makeText(this,"내장 브라우저에서 채널 영상을 열면 분류할 수 있어요",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("채널 분류 · 변경 이후 기록에 적용").setItems(names,(d,i)->{JSONObject row=list.optJSONObject(i);new AlertDialog.Builder(this).setTitle(row.optString("name")).setItems(new String[]{"강의","여가","미분류"},(dd,j)->{AnalyticsDb.get(this).channel(row.optString("id"),row.optString("name"),new String[]{"lecture","leisure","unknown"}[j]);refresh();}).show();}).show();}
 public void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}
